    app.add_handler(MessageHandler(filters.Regex(r'^/start(?:@\w+)? (?:z_|or_)'), unavailable), group=group)
    app.add_handler(MessageHandler(filters.StatusUpdate.WEB_APP_DATA, unavailable), group=group)
    return unavailable

